"""
Problem: LeetCode 3550 - Smallest Index With Digit Sum Equal to Index
Difficulty: Easy
Language: Python
Author: CodeByTushu
"""
from typing import List

class Solution:
    def smallestIndex(self, nums: List[int]) -> int:
        def digit_sum(n: int) -> int:
            s = 0
            while n > 0:
                s += n % 10
                n //= 10
            return s

        for i, val in enumerate(nums):
            if digit_sum(val) == i:
                return i
        return -1

